import numpy as np

VERSION = "KattBeauty Studio 0.20"
SETTINGS_DIR = Path(os.environ.get("KATTBEAUTY_SETTINGS_DIR", str(Path(os.environ.get("LOCALAPPDATA", str(Path.home()))) / "KattBeautyStudio")))
SETTINGS_DIR.mkdir(parents=True, exist_ok=True)
CONFIG = SETTINGS_DIR / "ajustes.json"
LEGACY_CONFIG = Path(__file__).with_name("kattbeauty_pestanas_textura_ajustes.json")
DEFAULTS = dict(color=1, eye=0.30, liner=2, ink=0.50, width=1.0,
                lash=2, lash_ink=0.70, length=1.0, shadow=True,
                blush=False, lips=True, lip_ink=0.55, makeup=0.35, slim=0.20, nose=0.25, nose_width=0.10, nose_profile=0.20, tip_lift=0.0,
                liner_offset=0.025, liner_left=0.0, liner_right=0.0,
                wing_lift=-0.025, wing_length=1.0)
COLORS = {1: ("Verde", (70, 205, 85)), 2: ("Azul", (245, 155, 65)),
          3: ("Verde olivo", (65, 140, 118)),
          4: ("Azul grisaceo", (175, 142, 109)),
          5: ("Avellana", (45, 175, 220)),
          6: ("Miel", (55, 140, 190)), 7: ("Gris plata", (160, 157, 152)),
          8: ("Jade", (113, 155, 93)), 9: ("Cafe", (45, 80, 120))}
LINERS = {0: "Sin", 1: "Fino", 2: "Cat eye", 3: "Intenso",
          4: "Foxy alargado", 5: "Difuminado cafe",6:"Glam lagrimal",7:"Douyin suave"}
LASHES = {0: "Sin", 1: "Flutter", 2: "Cat eye textura", 3: "Mink volumen",4:"Foxy suave",5:"Wispy densa",6:"Volumen suave"}
EYES = [
    dict(contour=[33,7,163,144,145,153,154,155,133,173,157,158,159,160,161,246],
         upper=[33,246,161,160,159,158,157,173,133], corners=[33,133],
         lids=[159,145], center=468, iris=[469,470,471,472]),
    dict(contour=[263,249,390,373,374,380,381,382,362,398,384,385,386,387,388,466],
         upper=[263,466,388,387,386,385,384,398,362], corners=[263,362],
         lids=[386,374], center=473, iris=[474,475,476,477]),
]
TEXTURE_MIPS = {}
LASH_ATLAS_PNG = ""
DECODED_ATLAS = None


class LatestCamera:
    """Un solo fotograma pendiente: descarta los antiguos si hay retraso."""
    def __init__(self, camera):
        self.camera = camera
        self.frames = queue.Queue(maxsize=1)
        self.stop = threading.Event()
        self.thread = threading.Thread(target=self._capture, daemon=True)
        self.thread.start()

    def _capture(self):
        while not self.stop.is_set():
            ok, frame = self.camera.read()
            try:
                self.frames.get_nowait()
            except queue.Empty:
                pass
            self.frames.put_nowait((ok, frame))
            if not ok:
                break

    def read(self):
        try:
            return self.frames.get(timeout=3)
        except queue.Empty:
            return False, None

    def close(self):
        self.stop.set()
        self.thread.join(timeout=1)


RANGES = {"width":(.4,3.),"length":(.4,2.),
          "liner_offset":(-.06,.10),"wing_lift":(-.12,.12),"wing_length":(.6,1.5),"liner_left":(-.05,.05),"liner_right":(-.05,.05)}

def normalize_settings(saved):
    result=DEFAULTS.copy()
    if not isinstance(saved,dict):
        return result
    for key,default in DEFAULTS.items():
        value=saved.get(key)
        if isinstance(default,bool):
            if isinstance(value,bool):result[key]=value
        elif isinstance(default,int):
            limit={"color":9,"liner":7,"lash":6}[key]
            if type(value) is int and 0<=value<=limit:result[key]=value
        elif type(value) in (int,float) and math.isfinite(value):
            low,high=RANGES.get(key,(0.,1.))
            result[key]=float(np.clip(value,low,high))
    return result


def load_settings():
    try:
        source=CONFIG if CONFIG.exists() else LEGACY_CONFIG
        return normalize_settings(json.loads(source.read_text(encoding="utf-8-sig")))
    except (OSError,ValueError,TypeError):
        return DEFAULTS.copy()


def save_settings(settings):
    try:
        temporary = CONFIG.with_suffix(".tmp")
        temporary.write_text(json.dumps(settings, indent=2), encoding="utf-8")
        temporary.replace(CONFIG)
        return True
    except OSError as error:
        print("No se pudieron guardar los ajustes:", error)
        return False


def geometry(points, eye):
    outer, inner = points[eye["corners"]]
    upper, lower = points[eye["lids"]]
    width = float(np.linalg.norm(inner - outer))
    inward = (inner - outer) / max(width, 0.001)
    up = np.array([inward[1], -inward[0]], dtype=np.float32)
    if np.dot(up, upper - lower) < 0:
        up = -up
    opening = float(np.linalg.norm(upper - lower)) / max(width, 0.001)
    return outer, width, inward, up, opening


def mix(frame, mask, color, strength):
    alpha = np.clip(mask * strength, 0, 1)[..., None]
    return np.clip(frame.astype(np.float32) * (1-alpha)
                   + np.asarray(color, np.float32) * alpha, 0, 255).astype(np.uint8)


def eyes_color(frame, points, settings):
    color=settings["color"]
    if color not in COLORS or settings["eye"]<=0:
        return frame
    output=frame.copy()
    height,width=frame.shape[:2]
    for eye in EYES:
        _,ew,_,_,opening=geometry(points,eye)
        blink=float(np.clip((opening-.10)/.10,0,1))
        if ew<8 or blink<=0:
            continue
        center=points[eye["center"]]
        iris=points[eye["iris"]]
        radius=float(np.linalg.norm(iris-center,axis=1).mean())
        if radius<1 or radius>ew*.45:
            continue
        margin=int(math.ceil(radius+3))
        cx,cy=center
        x0,x1=max(0,int(cx)-margin),min(width,int(cx)+margin+1)
        y0,y1=max(0,int(cy)-margin),min(height,int(cy)+margin+1)
        if x1<=x0 or y1<=y0:
            continue
        # Elipse real del iris: la textura acompana su inclinacion y su tamano.
        axis_x=(iris[0]-iris[2])*.5
        axis_y=(iris[1]-iris[3])*.5
        determinant=float(axis_x[0]*axis_y[1]-axis_x[1]*axis_y[0])
        yy,xx=np.mgrid[y0:y1,x0:x1]
        dx,dy=xx-cx,yy-cy
        if abs(determinant)>radius*radius*.15:
            u=(dx*axis_y[1]-dy*axis_y[0])/determinant
            v=(dy*axis_x[0]-dx*axis_x[1])/determinant
        else:
            u,v=dx/radius,dy/radius
        distance=np.sqrt(u*u+v*v)
        angle=np.arctan2(v,u)
        visible=np.zeros((y1-y0,x1-x0),np.uint8)
        polygon=np.rint(points[eye["contour"]]-[x0,y0]).astype(np.int32)
        cv2.fillPoly(visible,[polygon],255)
        mask=np.clip((.99-distance)/.13,0,1)*np.clip((distance-.30)/.17,0,1)
        mask*=visible.astype(np.float32)/255.*blink
        crop=frame[y0:y1,x0:x1]
        hsv=cv2.cvtColor(crop,cv2.COLOR_BGR2HSV)
        original_value=hsv[:,:,2].astype(np.float32)
        target=cv2.cvtColor(np.uint8([[COLORS[color][1]]]),cv2.COLOR_BGR2HSV)[0,0]
        # Anillo interior calido y borde exterior discreto, inspirados en las referencias.
        warm=np.exp(-((distance-.47)/.16)**2)*(.40 if color in (1,3,5,6,8,9) else .14)
        inner_hue=28. if color in (3,5,6,9) else (38. if color in (1,8) else 40.)
        hue=float(target[0])*(1-warm)+inner_hue*warm
        saturation=float(target[1])*(1-warm)+95.*warm
        # Fibras de poco contraste; sin copiar texturas ni reflejos de las fotografias.
        fibers=1.+.065*np.sin(angle*43.+2*np.sin(angle*11.)+distance*7.)
        fibers+=.035*np.sin(angle*89.-distance*13.)
        limbal=1.-.18*np.exp(-((distance-.88)/.075)**2)
        lift=np.minimum(36.,(255.-original_value)*.18)
        value=(original_value+lift)*fibers*limbal
        if color==9:
            value=original_value*.92*fibers*limbal
        tinted=hsv.copy()
        tinted[:,:,0]=np.clip(hue,0,179).astype(np.uint8)
        tinted[:,:,1]=np.clip(saturation*.80+hsv[:,:,1].astype(np.float32)*.20,0,165).astype(np.uint8)
        tinted[:,:,2]=np.clip(value,0,255).astype(np.uint8)
        colored=cv2.cvtColor(tinted,cv2.COLOR_HSV2BGR)
        highlights=np.clip((original_value-175.)/65.,0,1)
        alpha=(mask*min(.92,settings["eye"]*1.7)*(1-highlights))[...,None]
        output[y0:y1,x0:x1]=np.clip(crop.astype(np.float32)*(1-alpha)+colored.astype(np.float32)*alpha,0,255).astype(np.uint8)
    return output


def tapered_fiber(canvas, start, control, tip, thickness, opacity):
    t = np.linspace(0, 1, 30, dtype=np.float32)[:,None]
    curve = (1-t)**2*start + 2*(1-t)*t*control + t**2*tip
    tangent = np.gradient(curve, axis=0)
    tangent /= np.maximum(np.linalg.norm(tangent,axis=1,keepdims=True), .001)
    normal = np.column_stack([-tangent[:,1],tangent[:,0]])
    half = thickness*.5*(1-t)**1.1
    polygon = np.concatenate([curve+normal*half,(curve-normal*half)[::-1]])
    cv2.fillPoly(canvas,[np.rint(polygon).astype(np.int32)],int(opacity),lineType=cv2.LINE_AA)


def make_lash_texture(style):
    if style in (4,5,6):
        base=make_lash_texture({4:2,5:1,6:3}[style])
        height,width=base.shape[:2]
        yy,xx=np.mgrid[:height,:width].astype(np.float32)
        u=xx/max(width-1,1)
        # Variantes de las texturas aprobadas, sin volver a dibujar rallitas.
        stretch={4:1.12,5:.94,6:1.05}[style]
        if style==4:stretch=.72+.50*(1-u)
        map_y=(height-1-(height-1-yy)/stretch).astype(np.float32)
        result=cv2.remap(base,xx,map_y,cv2.INTER_LINEAR,borderMode=cv2.BORDER_CONSTANT)
        if style==4:
            gate=np.clip((.96-u)/.32,0,1)
            result*=gate[...,None]
        elif style==5:
            neighbor=cv2.remap(result,np.maximum(0,xx-2.5),yy,cv2.INTER_LINEAR)
            result=result+neighbor*.32*(1-result[:,:,3:4])
        elif style==6:
            result=np.clip(result*1.12,0,1)
        return np.clip(result,0,1).astype(np.float32)
    global DECODED_ATLAS
    if DECODED_ATLAS is None:
        encoded=np.frombuffer(base64.b64decode(LASH_ATLAS_PNG),np.uint8)
        DECODED_ATLAS=cv2.imdecode(encoded,cv2.IMREAD_UNCHANGED)
        if DECODED_ATLAS is None or DECODED_ATLAS.shape[2]!=4:
            raise ValueError("No se pudo cargar el atlas de pestanas.")
    image=DECODED_ATLAS
    boundaries=[0,round(image.shape[0]*.34),round(image.shape[0]*.66),image.shape[0]]
    strip=image[boundaries[style-1]:boundaries[style]].copy()
    alpha=strip[:,:,3]
    yy,xx=np.where(alpha>40)
    if len(yy)<100:
        raise ValueError("Textura de pestanas vacia.")
    bottom=int(np.percentile(yy,99.5))
    top=int(np.percentile(yy,1))
    band=alpha[max(0,bottom-10):min(alpha.shape[0],bottom+3)]
    supported=np.flatnonzero((band>55).sum(axis=0)>=2)
    left,right=int(supported[0]),int(supported[-1])
    span=max(right-left,1)
    # Curva base de la tira; se elimina su arco antes de adaptarla al parpado.
    baselines=[]
    for column in range(alpha.shape[1]):
        support=np.flatnonzero(alpha[:,column]>55)
        baselines.append(float(support[-1]) if len(support) else float(bottom))
    baseline=np.asarray(baselines,np.float32)
    baseline=cv2.GaussianBlur(baseline[None,:],(0,0),4).ravel()
    baseline[:left]=baseline[left]
    baseline[right+1:]=baseline[right]
    texture_height=max(bottom-top,1)
    nominal_height={1:.28,2:.35,3:.33}[style]
    u=np.linspace(-.35,1.15,1200,dtype=np.float32)[None,:]
    h=np.linspace(.65,0,520,dtype=np.float32)[:,None]
    source_x=np.broadcast_to(left+u*span,(520,1200)).copy()
    source_base=np.interp(source_x,np.arange(len(baseline)),baseline)
    source_y=(source_base-h/nominal_height*texture_height).astype(np.float32)
    # Alfa premultiplicada evita halos al reducir y deformar la textura.
    premultiplied=strip.astype(np.float32)/255
    premultiplied[:,:,:3]*=premultiplied[:,:,3:4]
    return cv2.remap(premultiplied,source_x,source_y,cv2.INTER_LINEAR,
                     borderMode=cv2.BORDER_CONSTANT,borderValue=0)


def lash_mask(shape, points, eye, texture, size):
    height, width = shape
    outer, ew, inward, up, opening = geometry(points,eye)
    if ew < 8:
        return None
    # Al cerrar el ojo, la proyeccion de la pestana se acorta y desvanece.
    blink = float(np.clip((opening-.075)/.12,0,1))
    if blink <= 0:
        return None
    vertical_scale = size*(.40+.60*blink)
    path = points[eye["upper"]]
    along = ((path-outer)@inward)/ew
    above = ((path-outer)@up)/ew
    order = np.argsort(along)
    along, above = along[order], above[order]
    corners = np.array([outer+inward*ew*u+up*ew*h
                        for u in (-.35,1.15)
                        for h in (-.35,.65*vertical_scale+.30)])
    x0,y0 = np.maximum(np.floor(corners.min(axis=0)).astype(int)-3,0)
    x1,y1 = np.minimum(np.ceil(corners.max(axis=0)).astype(int)+4,[width,height])
    if x1 <= x0 or y1 <= y0:
        return None
    yy,xx = np.mgrid[y0:y1,x0:x1]
    dx,dy = xx-outer[0],yy-outer[1]
    u = (dx*inward[0]+dy*inward[1])/ew
    h = (dx*up[0]+dy*up[1])/ew
    baseline = np.interp(u,along,above)
    local_h = (h-baseline)/max(vertical_scale,.01)
    # Prefiltra al tamano del ojo para que fibras subpixel no se vean punteadas.
    tw=max(32,round(ew*1.5*1.5/4)*4)
    th=max(24,round(ew*.65*vertical_scale*1.5/4)*4)
    cache_key=(id(texture),tw,th)
    filtered=TEXTURE_MIPS.get(cache_key)
    if filtered is None:
        filtered=cv2.resize(texture,(tw,th),interpolation=cv2.INTER_AREA)
        if len(TEXTURE_MIPS)>=96:
            TEXTURE_MIPS.clear()
        TEXTURE_MIPS[cache_key]=filtered
    map_x = ((u+.35)/1.5*(filtered.shape[1]-1)).astype(np.float32)
    map_y = ((.65-local_h)/.65*(filtered.shape[0]-1)).astype(np.float32)
    sampled = cv2.remap(filtered,map_x,map_y,cv2.INTER_LINEAR,
                        borderMode=cv2.BORDER_CONSTANT,borderValue=0)
    return x0,y0,x1,y1,sampled*blink


def apply_lashes(frame,points,settings,textures):
    if settings["lash"] == 0:
        return frame
    out = frame.copy()
    for eye in EYES:
        result = lash_mask(frame.shape[:2],points,eye,
                           textures[settings["lash"]],settings["length"])
        if result is not None:
            x0,y0,x1,y1,rgba = result
            opacity=settings["lash_ink"]
            original=out[y0:y1,x0:x1].astype(np.float32)
            alpha=np.clip(rgba[:,:,3:4]*opacity,0,1)
            out[y0:y1,x0:x1]=np.clip(original*(1-alpha)
                +rgba[:,:,:3]*255*opacity,0,255).astype(np.uint8)
    return out


def apply_liner(frame,points,settings):
    if settings["liner"] == 0:
        return frame
    height,width = frame.shape[:2]
    scale = 3
    mask = np.zeros((height*scale,width*scale),np.uint8)
    # Recupera la forma del delineado grueso aprobado en la prueba anterior.
    ratio,tail,lift = {1:(.085,.12,.07),2:(.140,.28,.16),3:(.185,.36,.21),
                       4:(.090,.38,.10),5:(.115,.22,.10),
                       6:(.125,.31,.18),7:(.065,.24,.04)}[settings["liner"]]
    for eye_index,eye in enumerate(EYES):
        outer,ew,inward,up,_ = geometry(points,eye)
        if ew < 8:
            continue
        offset=settings.get("liner_offset",.025)+settings.get("liner_left" if eye_index==0 else "liner_right",0.)
        shift=-up*ew*offset
        path = points[eye["upper"]]+shift
        outer=outer+shift
        thickness = max(.8,ew*ratio*settings["width"])
        if settings["liner"] == 4:
            # Foxy: banda estrecha en el centro y cola mas horizontal y larga.
            widths=np.array([.8,1,.9,.65,.45,.30,.18,.09,.02],np.float32)*thickness
        else:
            widths = np.linspace(1.,.18,len(path),dtype=np.float32)*thickness
        top = path+up[None,:]*widths[:,None]
        band = np.concatenate([path,top[::-1]])
        cv2.fillPoly(mask,[np.rint(band*scale).astype(np.int32)],255,lineType=cv2.LINE_AA)
        tip = outer-inward*ew*tail*settings.get("wing_length",1.)+up*ew*(lift+settings.get("wing_lift",-.025))
        wing = np.array([outer,tip,top[0],top[2]])
        cv2.fillPoly(mask,[np.rint(wing*scale).astype(np.int32)],255,lineType=cv2.LINE_AA)
        if settings["liner"] == 6:
            inner=points[eye["corners"][1]]+shift
            # Lagrimal puntiagudo como la referencia glam.
            inner_tip=inner+inward*ew*.10-up*ew*.025
            triangle=np.array([inner,inner_tip,path[-2]+up*thickness*.25])
            cv2.fillPoly(mask,[np.rint(triangle*scale).astype(np.int32)],255,lineType=cv2.LINE_AA)
        elif settings["liner"] == 7:
            # Delineado inferior exterior corto y suave, sin cerrar todo el ojo.
            lower_ids=eye["contour"][:5]
            lower=points[lower_ids]+(-up)[None,:]*ew*.018
            cv2.polylines(mask,[np.rint(lower*scale).astype(np.int32)],False,110,
                          max(1,round(ew*.012*scale*settings["width"])),cv2.LINE_AA)
    mask = cv2.resize(mask,(width,height),interpolation=cv2.INTER_AREA).astype(np.float32)/255
    if settings["liner"] == 5:
        eye_width=max(geometry(points,eye)[1] for eye in EYES)
        haze=cv2.GaussianBlur(mask,(0,0),max(.7,eye_width*.025))
        mask=np.clip(mask*.55+haze*.65,0,1)
        return mix(frame,mask,(34,27,43),settings["ink"])
    return mix(frame,mask,(14,10,12),settings["ink"])


def soft_makeup(frame,points,settings):
    height,width = frame.shape[:2]
    face_width = float(np.linalg.norm(points[234]-points[454]))
    blur = max(.7,face_width*.016)
    out = frame
    if settings["shadow"]:
        mask = np.zeros((height,width),np.uint8)
        eye_clear = np.zeros_like(mask)
        for eye in EYES:
            _,ew,_,up,_ = geometry(points,eye)
            path = points[eye["upper"]]
            heights = np.array([.04,.13,.18,.20,.21,.18,.13,.07,.01])*ew
            top = path+up[None,:]*heights[:,None]
            polygon = np.concatenate([path,top[::-1]])
            cv2.fillPoly(mask,[np.rint(polygon).astype(np.int32)],255)
            cv2.fillPoly(eye_clear,[np.rint(points[eye["contour"]]).astype(np.int32)],255)
        mask = cv2.GaussianBlur(mask,(0,0),blur).astype(np.float32)/255
        mask *= 1-eye_clear.astype(np.float32)/255
        out = mix(out,mask,(65,57,72),settings["makeup"]*.65)
    if settings["blush"]:
        mask = np.zeros((height,width),np.uint8)
        for index in (50,280):
            center = tuple(np.rint(points[index]).astype(int))
            cv2.ellipse(mask,center,(max(1,int(face_width*.12)),max(1,int(face_width*.065))),
                        0,0,360,255,-1,cv2.LINE_AA)
        mask = cv2.GaussianBlur(mask,(0,0),max(1,face_width*.035)).astype(np.float32)/255
        out = mix(out,mask,(105,106,195),settings["makeup"]*.45)
    if settings["lips"]:
        outer=[61,185,40,39,37,0,267,269,270,409,291,375,321,405,314,17,84,181,91,146]
        inner=[78,191,80,81,82,13,312,311,310,415,308,324,318,402,317,14,87,178,88,95]
        mask = np.zeros((height,width),np.uint8)
        hole = np.zeros_like(mask)
        cv2.fillPoly(mask,[np.rint(points[outer]).astype(np.int32)],255)
        cv2.fillPoly(hole,[np.rint(points[inner]).astype(np.int32)],255)
        mask = cv2.GaussianBlur(mask,(0,0),max(.7,face_width*.005)).astype(np.float32)/255
        mask *= 1-hole.astype(np.float32)/255
        # Carmesi con luminosidad del labio original, sin aplicar una capa plana.
        lab=cv2.cvtColor(out,cv2.COLOR_BGR2LAB)
        tinted=lab.copy()
        target=cv2.cvtColor(np.uint8([[[45,30,160]]]),cv2.COLOR_BGR2LAB)[0,0]
        for channel in (1,2):
            chroma=lab[:,:,channel].astype(np.float32)*.30+float(target[channel])*.70
            tinted[:,:,channel]=np.clip(chroma,0,255).astype(np.uint8)
        colored=cv2.cvtColor(tinted,cv2.COLOR_LAB2BGR)
        highlight=np.clip((lab[:,:,0].astype(np.float32)-195)/60,0,1)
        alpha=(mask*settings["lip_ink"]*(1-.8*highlight))[...,None]
        out=np.clip(out.astype(np.float32)*(1-alpha)+colored.astype(np.float32)*alpha,0,255).astype(np.uint8)
    return out


def eye_bounds(shape,points):
    height,width=shape
    ids=EYES[0]["contour"]+EYES[1]["contour"]
    bounds=points[ids]
    eye_width=max(geometry(points,eye)[1] for eye in EYES)
    # Margen para colitas y pestanas incluso con longitud al 200%.
    margin=max(8,int(math.ceil(eye_width*1.5)))
    x0,y0=np.maximum(np.floor(bounds.min(axis=0)).astype(int)-margin,0)
    x1,y1=np.minimum(np.ceil(bounds.max(axis=0)).astype(int)+margin+1,[width,height])
    return int(x0),int(y0),int(x1),int(y1)


def face_remap_coordinates(shape,points,strength):
    left,right=points[234],points[454]
    axis=right-left
    face_width=float(np.linalg.norm(axis))
    if face_width<30:return None
    axis/=face_width
    forehead,chin=points[10],points[152]
    down=np.array([-axis[1],axis[0]],np.float32)
    if np.dot(down,chin-forehead)<0:down=-down
    face_height=float(np.dot(chin-forehead,down))
    if face_height<40:return None
    center=(forehead+chin)*.5
    half_width,half_height=face_width*.5,face_height*.5
    corners=np.array([center+axis*half_width*u+down*half_height*v
                      for u in (-1.5,1.5) for v in (-1.35,1.35)])
    height,width=shape
    x0,y0=np.maximum(np.floor(corners.min(axis=0)).astype(int)-2,0)
    x1,y1=np.minimum(np.ceil(corners.max(axis=0)).astype(int)+3,[width,height])
    if x1<=x0 or y1<=y0:return None
    yy,xx=np.mgrid[y0:y1,x0:x1]
    u=((xx-center[0])*axis[0]+(yy-center[1])*axis[1])/half_width
    v=((xx-center[0])*down[0]+(yy-center[1])*down[1])/half_height
    # Mesma escala horizontal en frente, pomulos y mandibula; sin punta en V.
    fade_x=np.clip((1.48-np.abs(u))/.48,0,1)
    fade_y=np.clip((1.32-np.abs(v))/.32,0,1)
    fade_x=fade_x*fade_x*(3-2*fade_x)
    fade_y=fade_y*fade_y*(3-2*fade_y)
    compression=.10*float(np.clip(strength,0,1))
    displacement=u*half_width*(1/(1-compression)-1)*fade_x*fade_y
    mx=(xx-x0+displacement*axis[0]).astype(np.float32)
    my=(yy-y0+displacement*axis[1]).astype(np.float32)
    return x0,y0,x1,y1,mx,my


def slim_face(frame,points,strength):
    if strength<=0:return frame
    maps=face_remap_coordinates(frame.shape[:2],points,strength)
    if maps is None:return frame
    x0,y0,x1,y1,mx,my=maps
    out=frame.copy()
    out[y0:y1,x0:x1]=cv2.remap(frame[y0:y1,x0:x1],mx,my,cv2.INTER_LINEAR,borderMode=cv2.BORDER_REFLECT_101)
    return out


def nose_shape(frame,points,settings):
    narrow=settings.get("nose_width",0.)
    profile=settings.get("nose_profile",0.)
    lift=settings.get("tip_lift",0.)
    if max(narrow,profile,lift)<=0:return frame
    bridge,middle,tip,left,right=points[[168,6,1,98,327]]
    width=float(np.linalg.norm(right-left))
    axis=points[454]-points[234]
    fw=float(np.linalg.norm(axis))
    if width<6 or fw<30:return frame
    axis/=fw
    down=np.array([-axis[1],axis[0]],np.float32)
    if np.dot(down,points[152]-points[10])<0:down=-down
    length=float(np.dot(tip-bridge,down))
    if length<8 or length>width*7:return frame
    anchors=points[[168,6,1,98,327]]
    height,image_width=frame.shape[:2]
    margin=int(math.ceil(width*.8))
    x0,y0=np.maximum(np.floor(anchors.min(axis=0)).astype(int)-margin,0)
    x1,y1=np.minimum(np.ceil(anchors.max(axis=0)).astype(int)+margin+1,[image_width,height])
    if x1<=x0 or y1<=y0:return frame
    yy,xx=np.mgrid[y0:y1,x0:x1]
    dx,dy=xx-tip[0],yy-tip[1]
    u=dx*axis[0]+dy*axis[1]
    v=dx*down[0]+dy*down[1]
    # Perfil estimado en 2D: reduce la proyeccion hacia el lado del giro.
    yaw=float(np.clip(np.dot(tip-bridge,axis)/max(width,.001),-1,1))
    visibility=float(np.clip((abs(yaw)-.12)/.55,0,1))
    local=np.exp(-.5*((u/(width*.60))**2+(v/(length*.65))**2))
    shape_dx=width*.10*narrow*np.tanh(u/max(width*.25,.1))*local
    shape_dx+=width*.13*profile*np.sign(yaw)*visibility*local
    tip_mask=np.exp(-.5*((u/(width*.42))**2+(v/(width*.37))**2))
    shape_dy=width*.08*lift*tip_mask
    # Desvanecer completamente antes del borde para evitar costuras.
    edge=np.minimum.reduce([xx-x0,x1-1-xx,yy-y0,y1-1-yy])
    taper=np.clip(edge/max(2,width*.18),0,1)
    mx=(xx-x0+(shape_dx*axis[0]+shape_dy*down[0])*taper).astype(np.float32)
    my=(yy-y0+(shape_dx*axis[1]+shape_dy*down[1])*taper).astype(np.float32)
    out=frame.copy()
    out[y0:y1,x0:x1]=cv2.remap(frame[y0:y1,x0:x1],mx,my,cv2.INTER_LINEAR,borderMode=cv2.BORDER_REFLECT_101)
    return out


def nose_contour(frame, points, strength):
    """Sombras/luz en recorte local, sin deformar la imagen ni pintar la punta."""
    if strength<=0 or len(points)<468:
        return frame
    ids=[168,6,1,98,327]
    anchors=points[ids]
    if not np.isfinite(anchors).all():
        return frame
    bridge,middle,tip,left,right=anchors
    across=right-left
    width=float(np.linalg.norm(across))
    axis=tip-bridge
    length=float(np.linalg.norm(axis))
    if width<6 or length<8 or length>width*5:
        return frame
    down=axis/length
    across=across-down*np.dot(across,down)
    across_length=float(np.linalg.norm(across))
    if across_length<width*.35:
        return frame
    across/=across_length
    # Baja el contorno en giros fuertes para que no cruce al lado visible.
    dl=abs(float(np.dot(tip-left,across)))
    dr=abs(float(np.dot(right-tip,across)))
    symmetry=min(dl,dr)/max(dl,dr,.001)
    fade=float(np.clip((symmetry-.12)/.45,0,1))
    if fade<=0:
        return frame
    height,image_width=frame.shape[:2]
    margin=max(4,int(np.ceil(width*.65)))
    x0,y0=np.maximum(np.floor(anchors.min(axis=0)).astype(int)-margin,0)
    x1,y1=np.minimum(np.ceil(anchors.max(axis=0)).astype(int)+margin+1,[image_width,height])
    if x1<=x0 or y1<=y0:
        return frame
    shape=(y1-y0,x1-x0)
    origin=np.array([x0,y0],np.float32)
    shadow=np.zeros(shape,np.uint8)
    t=np.linspace(0,1,24,dtype=np.float32)
    # Curva suavizada sobre los puntos reales del puente y del centro nasal.
    centers=(1-t[:,None])**2*bridge+2*(1-t[:,None])*t[:,None]*middle+t[:,None]**2*tip
    offsets=width*(.17+.17*t)
    for sign in (-1,1):
        curve=centers+sign*offsets[:,None]*across
        cv2.polylines(shadow,[np.rint(curve-origin).astype(np.int32)],False,255,
                      max(1,round(width*.07)),cv2.LINE_AA)
    sigma=max(.8,width*.09)
    shade=cv2.GaussianBlur(shadow,(0,0),sigma).astype(np.float32)/255.
    if shade.max()>0:
        shade/=shade.max()
    yy,xx=np.mgrid[y0:y1,x0:x1]
    depth=((xx-bridge[0])*down[0]+(yy-bridge[1])*down[1])/length
    taper=np.clip(depth/.22,0,1)*np.clip((1.02-depth)/.28,0,1)
    shade*=taper
    central=np.zeros(shape,np.uint8)
    cv2.polylines(central,[np.rint(centers-origin).astype(np.int32)],False,255,
                  max(1,round(width*.045)),cv2.LINE_AA)
    light=cv2.GaussianBlur(central,(0,0),max(.7,width*.065)).astype(np.float32)/255.
    if light.max()>0:
        light/=light.max()
    light*=taper
    crop=frame[y0:y1,x0:x1]
    value=crop.max(axis=2).astype(np.float32)/255.
    amount=float(np.clip(strength,0,1))*fade
    # Multiplicacion suave: conserva poros, tonos y sombras existentes.
    gain=1-.18*amount*shade+.07*amount*light*(1-value)
    changed=np.clip(np.rint(crop.astype(np.float32)*gain[...,None]),0,255).astype(np.uint8)
    output=frame.copy()
    output[y0:y1,x0:x1]=changed
    return output


def render(frame,points,settings,textures):
    if len(points) < 478 or not np.isfinite(points).all():
        return frame
    x0,y0,x1,y1=eye_bounds(frame.shape[:2],points)
    if x1<=x0 or y1<=y0:
        return frame
    out=frame.copy()
    # Rubor y labios, opcionales, se procesan en un recorte del rostro.
    if settings["blush"] or settings["lips"]:
        height,width=frame.shape[:2]
        face=points[:468]
        fx0,fy0=np.maximum(np.floor(face.min(axis=0)).astype(int)-8,0)
        fx1,fy1=np.minimum(np.ceil(face.max(axis=0)).astype(int)+9,[width,height])
        if fx1>fx0 and fy1>fy0:
            local=settings.copy()
            local["shadow"]=False
            out[fy0:fy1,fx0:fx1]=soft_makeup(out[fy0:fy1,fx0:fx1],
                points-np.array([fx0,fy0],np.float32),local)
    cropped=out[y0:y1,x0:x1]
    shifted=points-np.array([x0,y0],np.float32)
    if settings["shadow"]:
        local=settings.copy()
        local.update(blush=False,lips=False)
        cropped=soft_makeup(cropped,shifted,local)
    cropped=eyes_color(cropped,shifted,settings)
    cropped=apply_liner(cropped,shifted,settings)
    cropped=apply_lashes(cropped,shifted,settings,textures)
    out[y0:y1,x0:x1]=cropped
    out=nose_contour(out,points,settings.get("nose",0.25))
    out=nose_shape(out,points,settings)
    return slim_face(out,points,settings["slim"])


def handle_key(key,settings):
    if 65 <= key <= 90:
        key += 32
    mappings = {ord("f"):("liner",1),ord("c"):("liner",2),ord("m"):("liner",3),ord("x"):("liner",0),
                ord("e"):("liner",4),ord("s"):("liner",5),
                0x740000:("liner",6),0x750000:("liner",7),
                ord("n"):("lash",1),ord("l"):("lash",2),ord("v"):("lash",3),ord("z"):("lash",0)}
    adjustments = {ord("-"):("eye",-.05,0,1),ord("+"):("eye",.05,0,1),ord("="):("eye",.05,0,1),
                   ord("j"):("ink",-.05,0,1),ord("k"):("ink",.05,0,1),
                   ord("u"):("width",-.1,.4,3),ord("i"):("width",.1,.4,3),
                   ord("b"):("lash_ink",-.05,0,1),ord("h"):("lash_ink",.05,0,1),
                   ord("t"):("length",-.1,.4,2),ord("y"):("length",.1,.4,2),
                   ord("d"):("makeup",-.05,0,1),ord("g"):("makeup",.05,0,1),
                   ord("w"):("slim",-.05,0,1),ord("r"):("slim",.05,0,1),
                   ord("["):("nose",-.05,0,1),ord("]"):("nose",.05,0,1),
                   0x720000:("lip_ink",-.05,0,1),0x730000:("lip_ink",.05,0,1)}
    if ord("0") <= key <= ord("9"):
        settings["color"] = key-ord("0")
    elif key in mappings:
        name,value=mappings[key]
        settings[name]=value
    elif key in adjustments:
        name,step,low,high=adjustments[key]
        settings[name]=round(float(np.clip(settings[name]+step,low,high)),2)
    elif key in (ord("o"),ord("a"),ord("p")):
        name={ord("o"):"shadow",ord("a"):"blush",ord("p"):"lips"}[key]
        settings[name]=not settings[name]
    elif key == 0x770000:
        settings.clear()
        settings.update(DEFAULTS)
    else:
        return False
    return True


def text(frame,line,position):
    for color,thickness in (((0,0,0),3),((255,255,255),1)):
        cv2.putText(frame,line,position,cv2.FONT_HERSHEY_SIMPLEX,.43,color,thickness,cv2.LINE_AA)


def main():
    if "--self-test" in sys.argv:
        import mediapipe as mp
        for style in range(1,7):
            assert make_lash_texture(style) is not None
        with mp.solutions.face_mesh.FaceMesh(max_num_faces=1,refine_landmarks=True) as detector:
            detector.process(np.zeros((64,64,3),np.uint8))
        print("Modelos y texturas cargados.")
        return 0
    if "--ui-smoke-test" in sys.argv:
        from kattbeauty_panel import Panel
        from types import SimpleNamespace
        app=Panel(SimpleNamespace(**globals()),start_worker=False)
        app.root.after(500,app.root.destroy)
        return app.run()
    from kattbeauty_panel import launch
    from types import SimpleNamespace
    return launch(SimpleNamespace(**globals()))


if __name__=="__main__":
    sys.exit(main())
